ALTER TABLE public.fixed_assets ADD COLUMN IF NOT EXISTS proposal_draft_id uuid REFERENCES public.finance_entry_drafts(id);
ALTER TABLE public.prepaid_schedules ADD COLUMN IF NOT EXISTS funding_draft_id uuid REFERENCES public.finance_entry_drafts(id);
CREATE OR REPLACE FUNCTION public.finance_schedule_source(t uuid,k text,ident uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN
IF k='asset' THEN SELECT to_jsonb(a) INTO v FROM fixed_assets a WHERE id=ident AND tenant_id=t FOR UPDATE;
ELSIF k='bill_line' THEN SELECT jsonb_build_object('line',to_jsonb(a),'bill',to_jsonb(b),'journal',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM journal_lines l WHERE l.entry_id=b.journal_entry_id AND l.tenant_id=t),'posted',(SELECT status FROM journal_entries WHERE id=b.journal_entry_id AND tenant_id=t)) INTO v FROM expense_bill_allocations a JOIN expense_bills b ON b.id=a.bill_id AND b.tenant_id=t WHERE a.id=ident AND a.tenant_id=t FOR UPDATE OF a,b;
ELSIF k='grni' THEN SELECT jsonb_build_object('grn',to_jsonb(g),'lines',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM grn_items l WHERE l.grn_id=g.id AND l.tenant_id=t),'invoice_posted',EXISTS(SELECT 1 FROM journal_entries e WHERE e.tenant_id=t AND e.status='posted' AND e.source_type='invoice' AND e.source_id=g.invoice_id::text)) INTO v FROM goods_received_notes g WHERE id=ident AND tenant_id=t FOR UPDATE;
ELSIF k='stock' THEN SELECT jsonb_build_object('count',to_jsonb(s),'lines',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM stock_count_items l WHERE l.session_id=s.id AND l.tenant_id=t),'prior',(SELECT to_jsonb(p) FROM stock_count_sessions p WHERE p.tenant_id=t AND p.venue=s.venue AND p.status='approved' AND p.count_date<s.count_date ORDER BY p.count_date DESC,p.approved_at DESC LIMIT 1),'prior_lines',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM stock_count_items l WHERE l.tenant_id=t AND l.session_id=(SELECT p.id FROM stock_count_sessions p WHERE p.tenant_id=t AND p.venue=s.venue AND p.status='approved' AND p.count_date<s.count_date ORDER BY p.count_date DESC,p.approved_at DESC LIMIT 1)),'basis',coalesce((SELECT stock_basis FROM finance_schedule_settings WHERE tenant_id=t),'purchases')) INTO v FROM stock_count_sessions s WHERE s.id=ident AND s.tenant_id=t FOR UPDATE; END IF;
IF v IS NULL THEN RAISE EXCEPTION 'Schedule source unavailable';END IF;RETURN v;END $$;
REVOKE ALL ON FUNCTION public.finance_schedule_source(uuid,text,uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.finance_asset_propose(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a fixed_assets;v jsonb;ident uuid;asset uuid;accum uuid;expense uuid;contra uuid;ls jsonb;amt numeric;depr numeric;cost numeric;gain uuid;loss uuid;act text:=p->>'action';d date:=(p->>'date')::date;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM finance_assert_open(t,d);PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));
IF act='disposal' THEN SELECT * INTO a FROM fixed_assets WHERE id=(p->>'asset')::uuid AND tenant_id=t FOR UPDATE;
IF NOT FOUND OR a.status NOT IN('active','fully_depreciated') OR a.notes IN('Opening proposal awaiting approval','Acquisition proposal awaiting approval') OR d<a.in_service_date THEN RAISE EXCEPTION 'Approved asset and valid disposal date required';END IF;
cost:=a.cost;depr:=a.amount_depreciated;amt:=(p->>'proceeds')::numeric;IF amt IS NULL OR amt<0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'Invalid disposal proceeds';END IF;contra:=(p->>'contra_account_id')::uuid;
IF amt>0 AND NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=contra AND is_active AND account_type='asset') THEN RAISE EXCEPTION 'Choose proceeds account';END IF;
ls:=jsonb_build_array(jsonb_build_object('account_id',a.asset_account_id,'debit',0,'credit',cost,'venue',a.venue),jsonb_build_object('account_id',a.accumulated_depr_account_id,'debit',depr,'credit',0,'venue',a.venue));
IF amt>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',contra,'debit',amt,'credit',0,'venue',a.venue));END IF;
IF cost-depr-amt>0 THEN loss:=finance_schedule_account(t,'6990','Asset disposal loss','other_expense');ls:=ls||jsonb_build_array(jsonb_build_object('account_id',loss,'debit',cost-depr-amt,'credit',0,'venue',a.venue));ELSIF cost-depr-amt<0 THEN gain:=finance_schedule_account(t,'4990','Asset disposal gain','other_income');ls:=ls||jsonb_build_array(jsonb_build_object('account_id',gain,'debit',0,'credit',amt-cost+depr,'venue',a.venue));END IF;
v:=finance_schedule_source(t,'asset',a.id);RETURN finance_schedule_enqueue(t,d,'asset_disposal',a.name||' · disposal','Confirmed disposal; original cost retained','asset-disposal:'||a.id,ls,jsonb_build_object('check_kind','asset','check_id',a.id,'fingerprint',md5(v::text),'asset',a.id,'proceeds',amt));
ELSIF act='acquisition' THEN cost:=(p->>'cost')::numeric;IF cost IS NULL OR cost<=0 OR cost<>round(cost,2) OR nullif(btrim(p->>'name'),'') IS NULL OR coalesce((p->>'life_months')::int,0)<=0 THEN RAISE EXCEPTION 'Invalid asset details';END IF;
asset:=finance_schedule_account(t,'1500','Fixed Assets','asset');accum:=finance_schedule_account(t,'1550','Accumulated Depreciation','asset');expense:=finance_schedule_account(t,'6900','Depreciation Expense','opex');contra:=(p->>'contra_account_id')::uuid;
IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=contra AND tenant_id=t AND is_active AND account_type IN('asset','liability','equity') AND id NOT IN(asset,accum)) THEN RAISE EXCEPTION 'Choose acquisition funding account';END IF;
INSERT INTO fixed_assets(tenant_id,name,category,purchase_date,in_service_date,cost,useful_life_months,venue,asset_account_id,accumulated_depr_account_id,expense_account_id,amount_remaining,notes,created_by) VALUES(t,p->>'name',p->>'category',d,d,cost,(p->>'life_months')::int,nullif(p->>'venue',''),asset,accum,expense,0,'Acquisition proposal awaiting approval',auth.uid()) RETURNING * INTO a;
ident:=finance_schedule_enqueue(t,d,'asset_acquisition',a.name||' · acquisition','Confirmed asset acquisition','asset-acquisition:'||a.id,jsonb_build_array(jsonb_build_object('account_id',asset,'debit',cost,'credit',0,'venue',a.venue),jsonb_build_object('account_id',contra,'debit',0,'credit',cost,'venue',a.venue)),jsonb_build_object('asset',a.id));UPDATE fixed_assets SET proposal_draft_id=ident WHERE id=a.id;RETURN ident;
ELSE RAISE EXCEPTION 'Unknown asset action';END IF;END $$;
REVOKE ALL ON FUNCTION public.finance_asset_propose(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_asset_propose(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_bill_schedule_propose(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb;a expense_bill_allocations;b expense_bills;asset uuid;accum uuid;expense uuid;ident uuid;reg uuid;sched uuid;amt numeric;share numeric;total numeric:=0;days int;startdate date;enddate date;cur date;ending date;ls jsonb;meta jsonb;d date:=(p->>'date')::date;k text:=p->>'kind';BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM finance_assert_open(t,d);PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));v:=finance_schedule_source(t,'bill_line',(p->>'line')::uuid);a:=jsonb_populate_record(NULL::expense_bill_allocations,v->'line');b:=jsonb_populate_record(NULL::expense_bills,v->'bill');
IF b.approval_status<>'posted' OR v->>'posted'<>'posted' OR a.amount<=0 OR NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=a.account_id AND tenant_id=t AND account_type IN('opex','cogs','other_expense')) OR coalesce((SELECT sum(debit-credit) FROM journal_lines WHERE tenant_id=t AND entry_id=b.journal_entry_id AND account_id=a.account_id),0)<a.amount THEN RAISE EXCEPTION 'Posted expense source required; save and approve the source bill first';END IF;
meta:=jsonb_build_object('check_kind','bill_line','check_id',a.id,'fingerprint',md5(v::text));
IF k='asset_reclassification' THEN IF a.amount<=coalesce((SELECT capitalisation_limit FROM finance_schedule_settings WHERE tenant_id=t),5000) OR EXISTS(SELECT 1 FROM fixed_assets WHERE tenant_id=t AND source_allocation_id=a.id) THEN RAISE EXCEPTION 'Line below capitalisation limit or already assigned';END IF;IF coalesce((p->>'life_months')::int,0)<=0 OR nullif(btrim(p->>'name'),'') IS NULL THEN RAISE EXCEPTION 'Confirm asset name and life';END IF;
asset:=finance_schedule_account(t,'1500','Fixed Assets','asset');accum:=finance_schedule_account(t,'1550','Accumulated Depreciation','asset');expense:=finance_schedule_account(t,'6900','Depreciation Expense','opex');INSERT INTO fixed_assets(tenant_id,name,category,purchase_date,in_service_date,cost,useful_life_months,venue,source_bill_id,source_allocation_id,asset_account_id,accumulated_depr_account_id,expense_account_id,amount_remaining,notes,created_by) VALUES(t,p->>'name',p->>'category',b.bill_date,d,a.amount,(p->>'life_months')::int,coalesce(a.venue,b.venue),b.id,a.id,asset,accum,expense,0,'Acquisition proposal awaiting approval',auth.uid()) RETURNING id INTO reg;
ls:=jsonb_build_array(jsonb_build_object('account_id',asset,'debit',a.amount,'credit',0,'venue',coalesce(a.venue,b.venue)),jsonb_build_object('account_id',a.account_id,'debit',0,'credit',a.amount,'venue',coalesce(a.venue,b.venue)));ident:=finance_schedule_enqueue(t,d,k,p->>'name','Owner-confirmed equipment reclassification; source bill unchanged','capitalise:'||a.id,ls,meta||jsonb_build_object('asset',reg),b.attachment_path,b.journal_entry_id);UPDATE fixed_assets SET proposal_draft_id=ident WHERE id=reg;RETURN ident;
ELSIF k='prepayment_funding' THEN IF EXISTS(SELECT 1 FROM prepaid_schedules WHERE tenant_id=t AND source_bill_id=b.id AND expense_account_id=a.account_id AND status<>'cancelled') THEN RAISE EXCEPTION 'Prepayment already exists for this bill and account';END IF;
startdate:=coalesce(b.service_period_start,b.period_start);enddate:=coalesce(b.service_period_end,b.period_end);IF startdate IS NULL OR enddate IS NULL OR enddate<startdate OR enddate>startdate+interval '10 years' THEN RAISE EXCEPTION 'Confirm covered dates on the source bill';END IF;
days:=enddate-startdate+1;cur:=date_trunc('month',startdate)::date;ending:=date_trunc('month',enddate)::date;
WHILE cur<=ending LOOP IF cur>date_trunc('month',b.bill_date)::date THEN total:=total+round(a.amount*(least(enddate,(cur+interval '1 month -1 day')::date)-greatest(startdate,cur)+1)/days,2);END IF;cur:=(cur+interval '1 month')::date;END LOOP;IF total<=0 THEN RAISE EXCEPTION 'No future coverage to defer';END IF;
asset:=finance_schedule_account(t,'1320','Prepayments','asset');cur:=greatest(date_trunc('month',startdate)::date,(date_trunc('month',b.bill_date)+interval '1 month')::date);
INSERT INTO prepaid_schedules(tenant_id,source_bill_id,supplier_id,supplier_account_id,venue_id,description,total_amount,prepaid_account_id,expense_account_id,start_period,num_periods,amount_remaining,status) VALUES(t,b.id,b.supplier_id,b.supplier_account_id,b.venue_id,coalesce(a.notes,a.expense_category,b.vendor_name,'Advance bill'),total,asset,a.account_id,cur,(extract(year FROM age(ending,cur))*12+extract(month FROM age(ending,cur))+1)::int,0,'active') RETURNING id INTO sched;
WHILE cur<=ending LOOP share:=round(a.amount*(least(enddate,(cur+interval '1 month -1 day')::date)-greatest(startdate,cur)+1)/days,2);INSERT INTO prepaid_schedule_lines(tenant_id,schedule_id,period,planned_amount) VALUES(t,sched,cur,share);cur:=(cur+interval '1 month')::date;END LOOP;
ls:=jsonb_build_array(jsonb_build_object('account_id',asset,'debit',total,'credit',0,'venue',coalesce(a.venue,b.venue)),jsonb_build_object('account_id',a.account_id,'debit',0,'credit',total,'venue',coalesce(a.venue,b.venue)));ident:=finance_schedule_enqueue(t,d,k,'Advance bill · prepayment','Day-based future coverage; original bill unchanged','prepaid-funding:'||a.id,ls,meta||jsonb_build_object('schedule',sched),b.attachment_path,b.journal_entry_id);UPDATE prepaid_schedules SET funding_draft_id=ident WHERE id=sched;RETURN ident;
ELSE RAISE EXCEPTION 'Unknown bill schedule';END IF;END $$;
REVOKE ALL ON FUNCTION public.finance_bill_schedule_propose(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_bill_schedule_propose(uuid,jsonb) TO authenticated;